function remainingAt(gainIndex, yearIndex, age) {
  const ages = LONGEVITY_AGE_MAX - LONGEVITY_AGE_MIN + 1;
  const a = Math.max(LONGEVITY_AGE_MIN, Math.min(LONGEVITY_AGE_MAX, Math.round(age)));
  return VALUES[(gainIndex * LONGEVITY_YEARS.length + yearIndex) * ages + (a - LONGEVITY_AGE_MIN)] / 10;
}

/** Remaining years of life for someone retiring at `age` in `year` (2026–2070). */
export function yearsCollectingPension(longevityGain = 0, year = 2026, age = 65) {
  const gIdx = Math.max(0, Math.min(LONGEVITY_GAIN_COUNT - 1, Math.round((Number(longevityGain) || 0) / LONGEVITY_GAIN_STEP)));
  const y = Math.max(LONGEVITY_YEARS[0], Math.min(LONGEVITY_YEARS.at(-1), year));
  let i = LONGEVITY_YEARS.findIndex(v => v >= y);
  if (LONGEVITY_YEARS[i] === y || i <= 0) return remainingAt(gIdx, Math.max(0, i), age) - Math.max(0, age - LONGEVITY_AGE_MAX);
  const y0 = LONGEVITY_YEARS[i - 1], y1 = LONGEVITY_YEARS[i];
  const t = (y - y0) / (y1 - y0);
  const v = remainingAt(gIdx, i - 1, age) * (1 - t) + remainingAt(gIdx, i, age) * t;
  return Math.max(0, v - Math.max(0, age - LONGEVITY_AGE_MAX));
}

/** Age reached on average by someone who retires at `age` in `year`. */
export function lifeExpectancyAtRetirement(longevityGain = 0, year = 2026, age = 65) {
  return age + yearsCollectingPension(longevityGain, year, age);
}
